const response = $input.first().json;
const originalEmail = $('Gmail Trigger').first().json;

const LABEL_MAP = {
  "AdQuadrant": "Label_1635244963453248173",
  "TikTok": "Label_1931679288864972310",
  "Asana": "Label_2117505959743628807",
  "Operations": "Label_2356661191061945189",
  "Google": "Label_4106205777453927081",
  "Meta": "Label_5536474334869364195",
  "Forwarded for James": "Label_7066207239495531100",
  "Affiliate Email Group": "Label_8145982436135018374",
  "Shopify": "Label_29",
  "Snapchat": "Label_27",
  "Reddit": "Label_30",
  "LinkedIn": "Label_28",
  "Pinterest": "Label_31"
};

let parsed;
try {
  let text = response.content[0].text;
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  parsed = JSON.parse(text);
} catch (e) {
  parsed = { class: 'UNKNOWN', data: { error: e.message }, org: {} };
}

// Resolve apply_labels names → IDs
const org = parsed.org || {};
const labelNames = org.apply_labels || [];
const applyLabelIds = labelNames.map(name => LABEL_MAP[name]).filter(Boolean);

parsed.email = {
  from: originalEmail.from || '',
  subject: originalEmail.subject || ''
};
parsed.emailId = originalEmail.id;
parsed.apply_label_ids = applyLabelIds;

return [{ json: parsed }];

